/*
 * Plugin Tutorial: 7-Segment Display Driver
 * 
 * This tutorial shows how to create a custom plugin for a 7-segment display.
 * 
 * STEPS TO CREATE THE PLUGIN:
 * 
 * 1. Create js/libraries/sevensegment.js with this structure:
 * 
 *    window.ArduinoLibs = window.ArduinoLibs || {};
 *    window.ArduinoLibs['SevenSegment'] = {
 *      classes: ['SevenSegment'],
 *      includes: ['<SevenSegment.h>'],
 *      priority: 50,
 *      transpile: [
 *        [/\b(\w+)\.begin\s*\(/g, fn],
 *        [/\b(\w+)\.writeDigit\s*\(/g, fn],
 *        [/\b(\w+)\.clear\s*\(/g, fn],
 *      ],
 *      runtime: function(self) { return { ... }; },
 *      constructor: function(args) { return { ... }; },
 *      constants: { COMMON_ANODE: 0, COMMON_CATHODE: 1 },
 *    };
 * 
 * 2. Add to index.html: <script src="js/libraries/sevensegment.js"></script>
 * 
 * 3. Use in sketch: #include <SevenSegment.h>
 * 
 * Circuit: 7-segment on D2-D8, Button on D9
 */

#include <SevenSegment.h>

// 7-segment pins: A=D2, B=D3, C=D4, D=D5, E=D6, F=D7, G=D8
SevenSegment display(2, 3, 4, 5, 6, 7, 8);

const int buttonPin = 9;
int count = 0;
bool lastButton = HIGH;

void setup() {
  Serial.begin(115200);
  pinMode(buttonPin, INPUT_PULLUP);

  display.begin(COMMON_CATHODE);
  display.clear();

  Serial.println(F("SevenSegment Plugin Demo"));
  Serial.println(F("Press button to increment"));
}

void loop() {
  bool button = digitalRead(buttonPin);

  if (button == LOW && lastButton == HIGH) {
    count = (count + 1) % 10;
    display.writeDigit(count);
    Serial.print(F("Display: "));
    Serial.println(count);
  }
  lastButton = button;

  delay(50);
}
